{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "initial",
  "supportive_card_ids": ["C03", "C04", "C10", "C14", "C12", "C23", "C20", "C06"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C03", "C04", "C10", "C14", "C12", "C23", "C20"],
  "claims": [
    {
      "claim": "Posaconazole, a large lipophilic 1,2,4-triazole antifungal with a tetrahydropyran and high molecular weight, showed absolute oral bioavailability of 42–56% in the fasted state and 85–87% in the fed state, all above the 20% threshold.",
      "card_ids": ["C03", "C04", "C10", "C14"]
    },
    {
      "claim": "Atazanavir, another high-molecular-weight/high-TPSA oral drug, showed >90% oral bioavailability when taken with food.",
      "card_ids": ["C12", "C23"]
    },
    {
      "claim": "UDCA, a triterpenoid carboxylic acid, showed 78–87% systemic availability in cirrhotic patients, supporting that a triterpenoid acid scaffold can achieve high oral bioavailability.",
      "card_ids": ["C20"]
    },
    {
      "claim": "No L1 record in any transferable context reports oral bioavailability below 20%; the lowest reported value is 35.9% for phenoxymethylpenicillin in underweight children.",
      "card_ids": ["C07"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "current_gold_voting_records",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "changed",
      "card_ids": ["C03", "C04", "C10", "C14", "C12", "C23", "C20"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule in humans or animals.",
    "No specified prandial state or formulation for the query; food effects may be substantial for a lipophilic triazole triterpenoid.",
    "Transferability from posaconazole, atazanavir, and UDCA contexts is inferred from structural and physicochemical similarity, not confirmed by query-specific pharmacokinetic data.",
    "The query's zwitterionic character and very high estimated logP may affect absorption, but no quantitative permeability or solubility data are provided."
  ],
  "decision_summary": "All transferable L1 records report oral bioavailability values above the 20% threshold, with the most relevant contexts (posaconazole, atazanavir, UDCA) showing 42–96% F. The physicochemical prior is an uncertain descriptor-based signal and is not affirmative evidence for F < 20%. Therefore F >= 20% is better supported."
}

